// 242. Valid Anagram

#include "libraries.cpp"

class Solution {
public:
    bool isAnagram(string s, string t) {
        if (s.size() != t.size()) {
            return false;
        }

        int count[26] = {0};
        int n = s.size();
        for (int i = 0; i < n; i++)
        {
            count[s[i] - 97] -= 1;
            count[t[i] - 97] += 1;
        }
        
        for (auto &&i : count)
        {
            if (i) {
                return false;
            }
        }
        return true;
    }
};

void test() {
    Solution s;
    // s.isAnagram("anagram", "nagaram");
    PRINT(s.isAnagram("anagram", "nagaram"));

    auto s1 = "";
    auto t = "";
    PRINT(s.isAnagram(s1, t));
}